INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('S-2026-10-07-CL90-KERNEL-CONTRACT-AUDIT','CL-90 static DiceBox kernel request and gate writer graph audit','verification','Central Lodge 21 Scenes / 115 RegionBehaviors','Foundry Playwright read-only source parser and state-path/requirement inspection','active','work/foundry-playwright-harness/cl90-kernel-request-contract-audit-v001.page.js; cl91-kernel-gate-writer-graph-v001.page.js','2026-10-07','97 literal action requests / 6 gates / 2 known schema exceptions','Read-only 30 pickups, 29 notices, 16 observes, 16 sockets, 6 gates; 3 separate dynamic GM-adjudicated CL-33 pickup script requests excluded from JSON-only parse. All six gates have producers for presently false state prerequisites, not proof of live player inventory or runtime canary. Two unresolved state-name differences are M2 founderPortraitOpened and U2 servantHistoryObserved.'),
('S-2026-10-07-CL90-KERNEL-SELFTEST-SMOKE','CL-90 runtime kernel selfTest plus reusable 21-Scene no-write smoke','verification','Central Lodge runtime safety','Shared kernel read-only selfTest plus independent Playwright source snapshot','active','work/foundry-playwright-harness/cl90-kernel-selftest-readonly-v001.page.js; cl90-progress-safety-smoke-v001.page.js','2026-10-07','Kernel 1.0.0 PASS; 21/202/115/33; ledger rev0','Read-only kernel selfTest returned PASS with 33 ledger/world canonical Items and no failures, executing Assistant GM nonprimary. Snapshot independently returned PASS_WITH_KNOWN_BLOCKERS, 115 unique stableIds and 0 disabled; intentionally excludes gameplay canary and tracks M1/N3 blocked Regions.'),
('S-2026-10-07-CL91-M1-N3-AUTHORED-BLOCKER-RECON','Source plan reconciliation of M1 grandfather clock and N3 T3 railway branch','verification','Central Lodge M1 and N3','Authoritative M1 PREPARE, U1 canonical fact and N3 safe-scope fact plus Foundry read-only introspection','active','docs/CL90-KERNEL-CONTRACT-CL91-BLOCKERS-2026-10-07.md; work/lodge-campaign/scenes/M1-entrance-hall-great-room/prepare/PREPARE-v001.md','2026-10-07','M1 correct time deferred CL-13; N3 branch prerequisite policy explicitly deferred','M1 family chronology indicates setting but gives no numeric literal, Region 3tIrR12uv8ppFkOb 0 behaviors; N3 branch Region RP1jYOH738xl9hks 0 behaviors, flag false. Original safe-scope explicitly prohibits setting unlock without resolving departure board/switch/overlay relationship.');

INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-2026-10-07-CL90-LITERAL-REQUEST-CONTRACT-GRAPH','campaign.central-lodge.qa',NULL,'CL90 read-only static kernel requests 97 parsed, 6 gates have state producers','Playwright read-only static parser examined 115 Lodge RegionBehaviors and parsed 97 literal DiceBox kernel requests (30 pickup, 29 notice, 16 observe, 16 socket, 6 gate), with 3 separately verified dynamic CL33 GM-adjudicated pickup scripts excluded. It found exactly two schema mismatches: M2 Founder Portrait Signet behavior IdriZEGhxUY9whcV uses puzzles.m2.founderPortraitOpened though canonical ledger has founderPortraitObserved; U2 Servant History Observation J11ZvQh4lqzEsvRi uses servantHistoryObserved though ledger has servantHistoryInterpreted. The six gate behaviors have zero currently false state requirements without a producer. M2 live source already checks for actor possession of canonical Founders Signet before Old Estate Survey pickup. Neither exception was automatically mutated due distinct physical reveal versus observation/interpreted semantics. No player canary.','campaign','static','locked','S-2026-10-07-CL90-KERNEL-CONTRACT-AUDIT',NULL,'central lodge cl90 runtime request 97 6 gate producers 2 schema exceptions'),
('F-2026-10-07-CL90-SELFTEST-SMOKE','campaign.central-lodge.qa',NULL,'Shared runtime kernel self-test and independent 21-Scene smoke PASS','In Playwright no-write mode, shared kernel selfTest returned PASS version 1.0.0, 33 canonical world Items and ledger Items, no failures; ledger revision stayed 0. Separate cl90-progress-safety-smoke-v001.page.js PASS_WITH_KNOWN_BLOCKERS confirmed 21 Scenes, 202 Regions, 115 enabled behaviors with 115 unique stable IDs, 33 Items and kernel SHA 6264c467211d4f5c94cfaaa9437eae88582599061b9d8a4951391830a3e8f814. M1 Clock Setting and N3 Branch Railway Regions remain empty by blocked authoring policy, no gameplay canary.','campaign','static','locked','S-2026-10-07-CL90-KERNEL-SELFTEST-SMOKE',NULL,'central lodge cl90 kernel selftest 21 202 115 33 zero drift'),
('F-2026-10-07-CL91-M1-N3-SOURCE-DEFERRED','campaign.central-lodge.progression',NULL,'M1 clock numeric solution and N3 T3 branch rule missing by explicit authoring deferral','M1 PREPARE says correct clock setting follows Silver Family Emblem plus family genealogy and grave records, and opens the compartment with Family Reliquary Key and Brass Baggage Token; existing U1 fact explicitly confirms no recovered numeric clock-hand literal and defers to CL13. M1 clock setting Region 3tIrR12uv8ppFkOb has no behavior and puzzles.m1.clockSettingResolved=false. N3 safe-scope explicitly defers t3BranchUnlocked until semantics joining Departure Board, Switch Wheel and Cartography Table are decided; N3 Branch Railway Region RP1jYOH738xl9hks has no behavior and flag false. GM approval for exact clock solution or chosen adjudication mode and exact N3 branch prerequisites required before writes.','campaign','static','locked','S-2026-10-07-CL91-M1-N3-AUTHORED-BLOCKER-RECON',NULL,'central lodge cl91 m1 clock solution n3 t3 branch authored deferral');
